(function(){'use strict';
const main=document.getElementById('career-main'),banks=window.CareerExplorerQuestions,scoring=window.CareerExplorerScoring,fx=window.ResourceFX;
const META={
 R:{name:'Realistic',label:'Building & doing',short:'Building',icon:'🛠️',color:'#b86a19',light:'#fff0cb'},
 I:{name:'Investigative',label:'Asking & discovering',short:'Discovering',icon:'🔍',color:'#16816f',light:'#d9f5e9'},
 A:{name:'Artistic',label:'Art & stories',short:'Creating',icon:'🎨',color:'#c04c8c',light:'#ffe3f1'},
 S:{name:'Social',label:'Helping & teaching',short:'Helping',icon:'🤝',color:'#7850c3',light:'#eee3ff'},
 E:{name:'Enterprising',label:'Leading & sharing ideas',short:'Leading',icon:'📣',color:'#b86522',light:'#ffecd3'},
 C:{name:'Conventional',label:'Organizing & planning',short:'Organizing',icon:'📋',color:'#326bbb',light:'#e0eeff'}
};
const OPTIONS=[{value:'yes',text:'Yes'},{value:'kinda',text:'Kind of'},{value:'not-really',text:'Not really'},{value:'nope',text:'No'}];
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let bank,answers,index=0,profile,lastCareerButton,searchGrade,activeCategory='all';
function storageKey(){return 'ocs_career_session_v2_'+bank.id}
function save(){try{sessionStorage.setItem(storageKey(),JSON.stringify({version:2,bankVersion:bank.version,answers,index}))}catch{}}
function restore(){answers=new Array(bank.questions.length).fill(null);try{const old=JSON.parse(sessionStorage.getItem(storageKey())||'null');if(old?.version===2&&old.bankVersion===bank.version&&Array.isArray(old.answers)&&old.answers.length===answers.length&&old.answers.every(a=>a===null||Object.hasOwn(scoring.SCORE_MAP,a))){answers=old.answers;index=Number.isInteger(old.index)?Math.max(0,Math.min(old.index,answers.length-1)):0}}catch{}}
function focus(selector,scroll=false){const el=main.querySelector(selector);if(!el)return;el.focus({preventScroll:true});if(scroll)el.scrollIntoView({behavior:fx.reducedMotion()?'auto':'smooth',block:'start'})}
function readButton(){return 'speechSynthesis'in window?'<button type="button" class="activity-read" data-read aria-pressed="false">Read aloud</button>':''}
function hub(){main.innerHTML=`<section class="page-intro"><h1>Career Explorer</h1><p>Choose your grade.</p></section><section class="grade-grid" aria-label="Grade groups">${Object.values(banks).map((b,i)=>`<article class="card grade-card grade-${i}"><div class="grade-art" aria-hidden="true">${['🧩','🌱','🔭'][i]}</div><h2>${b.label}</h2><p>${b.questions.length} questions about activities you enjoy.</p><a class="primary" href="${b.file}">Start ${b.label}</a></article>`).join('')}</section>`}
function quizIntro(){const done=answers.filter(a=>a!==null).length;main.innerHTML=`<section class="page-intro"><h1>Career Explorer</h1><p class="grade-context">${bank.label}</p></section><section class="card quiz-intro"><div class="intro-mascot" aria-hidden="true">${bank.id==='tkk'?'🌟':bank.id==='grades12'?'🚀':'🔭'}</div><h2>What do you like to do?</h2><p>Choose how much you like each activity. There are no right or wrong answers.</p>${bank.id==='tkk'?'<p>An adult can read the questions with you.</p>':''}<p class="question-count">${done?`${done} of ${answers.length} answered`:`${answers.length} questions`}</p><div class="intro-actions"><button type="button" class="primary" id="start-quiz">${done===answers.length?'See results':done?'Continue':'Start'}</button>${done?'<button type="button" class="secondary" id="restart-quiz">Start again</button>':''}</div><a class="text-link" href="careers.html?grade=${bank.id}">Browse jobs</a></section>`;document.getElementById('start-quiz').onclick=()=>{fx.tap();if(done===answers.length)results();else renderQuestion()};document.getElementById('restart-quiz')?.addEventListener('click',restart)}
function restart(){fx.stopReading();answers=new Array(bank.questions.length).fill(null);index=0;save();renderQuestion()}
function renderQuestion(){fx.stopReading();const q=bank.questions[index],done=answers.filter(a=>a!==null).length;
 main.innerHTML=`<section class="quiz-heading"><span>${bank.label}</span></section><section class="quiz-area"><div class="quiz-progress"><span id="question-count">Question ${index+1} of ${answers.length}</span><progress id="progress-native" value="${done}" max="${answers.length}" aria-label="Questions answered" aria-valuetext="${done} of ${answers.length} answered"></progress></div><div class="card question-card soft-enter"><div class="question-emoji" aria-hidden="true">${esc(q.emoji)}</div><h1 id="question-text" class="question-text" tabindex="-1">${esc(q.text)}</h1>${readButton()}<fieldset class="answers"><legend class="sr-only">How much do you like this activity?</legend>${OPTIONS.map(o=>`<label class="answer-choice choice-${o.value} ${answers[index]===o.value?'selected':''}"><input type="radio" name="interest" value="${o.value}" ${answers[index]===o.value?'checked':''}><span>${o.text}</span></label>`).join('')}</fieldset><div class="quiz-actions"><button type="button" class="secondary" id="previous-question">${index?'Back':'Back to start'}</button><button type="button" class="primary" id="next-question" ${answers[index]===null?'disabled':''}>${index+1===answers.length?'See results':'Next'}</button></div></div><a class="text-link browse-during-quiz" href="careers.html?grade=${bank.id}">Browse jobs</a><div class="sr-only" id="quiz-status" role="status" aria-live="polite"></div></section>`;
 main.querySelectorAll('input[name=interest]').forEach(input=>input.addEventListener('change',()=>{answers[index]=input.value;save();main.querySelectorAll('.answer-choice').forEach(label=>label.classList.toggle('selected',label.querySelector('input').checked));document.getElementById('next-question').disabled=false;const p=document.getElementById('progress-native'),n=answers.filter(a=>a!==null).length;p.value=n;p.setAttribute('aria-valuetext',`${n} of ${answers.length} answered`);fx.tap()}));
 document.getElementById('previous-question').onclick=()=>{if(index===0){fx.stopReading();quizIntro();focus('h2',true);return}index--;save();renderQuestion()};
 document.getElementById('next-question').onclick=()=>{if(answers[index]===null)return;if(index+1===answers.length){results();fx.complete()}else{index++;save();renderQuestion()}};
 main.querySelector('[data-read]')?.addEventListener('click',e=>fx.read(q.text+'. Choose: Yes. Kind of. Not really. No.',e.currentTarget));focus('#question-text',true);
}
function results(){fx.stopReading();profile=scoring.calculateProfile(bank.questions,answers);save();const allEqual=profile.status==='tied',none=profile.status==='no-preference';
 main.innerHTML=`<section class="page-intro"><h1 tabindex="-1">${none?'No favorites yet':'Your interests'}</h1><p>${none?'You can try again or explore any of the jobs.':allEqual?'You rated all six activity groups the same.':'These are the activities you liked most.'}</p></section><section class="result-chart card" aria-label="All six RIASEC activity scores"><h2>Your activity choices</h2>${profile.all.map(r=>{const m=META[r.code];return `<div class="score-row" data-code="${r.code}"><div class="score-label"><strong>${esc(m.label)}</strong><span>${m.name} · ${r.code}</span></div><div class="score-track" role="meter" aria-label="${esc(m.label)} points" aria-valuenow="${r.total}" aria-valuemin="0" aria-valuemax="${r.maxScore}"><span style="width:${r.percentage}%;background:${m.color}"></span></div><span class="score-value">${r.total}/${r.maxScore}</span></div>`}).join('')}</section>${none?'':`<section class="interest-grid" aria-label="Highest interest areas">${profile.top.map(r=>{const m=META[r.code];return `<article class="card interest-card" style="--area:${m.color};--area-light:${m.light}"><span class="interest-emoji" aria-hidden="true">${m.icon}</span><h2>${esc(m.label)}</h2>${r.tied?'<p class="tie-label">Same score as another group</p>':''}<div class="job-links">${bank.jobs[r.code].map(id=>`<button type="button" class="job-button" data-job="${id}" aria-expanded="false" aria-controls="career-profile">${esc(CareerExplorerData.careers[bank.id][id].label)}</button>`).join('')}</div></article>`}).join('')}</section>`}<section id="career-profile" class="card profile-panel" hidden></section><div class="results-actions no-print"><a class="primary" href="careers.html?grade=${bank.id}">Browse all jobs</a><button type="button" class="secondary" id="review-answers">Review answers</button><button type="button" class="secondary" id="retry">Start again</button></div>`;
 bindJobs(bank.id);document.getElementById('review-answers').onclick=()=>{index=0;renderQuestion()};document.getElementById('retry').onclick=restart;focus('h1',true);
}
function bindJobs(grade){main.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>{lastCareerButton=b;main.querySelectorAll('[data-job]').forEach(other=>other.setAttribute('aria-expanded',String(other===b)));showCareer(grade,b.dataset.job);fx.tap()})}
function showCareer(grade,id){fx.stopReading();const c=CareerExplorerData.careers[grade]?.[id],panel=document.getElementById('career-profile');if(!c||!panel)return;const day=Array.isArray(c.day)?c.day.map(v=>typeof v==='string'?v:(v.time?v.time+': ':'')+v.task):c.day?[c.day]:[];
 panel.hidden=false;panel.innerHTML=`<div class="profile-top"><h2 tabindex="-1">${esc(c.label)}</h2><button type="button" class="text-link" id="close-profile" aria-label="Close job details">Close</button></div><p class="profile-description">${esc(c.does)}</p>${readButton()}${day.length?`<h3 class="day-heading">A day at work</h3><ul class="day-list">${day.map(text=>`<li>${esc(text)}</li>`).join('')}</ul>`:''}`;panel.querySelector('[data-read]')?.addEventListener('click',e=>fx.read(c.label+'. '+c.does+'. '+day.join('. '),e.currentTarget));document.getElementById('close-profile').onclick=()=>{fx.stopReading();panel.hidden=true;main.querySelectorAll('[data-job]').forEach(b=>b.setAttribute('aria-expanded','false'));if(lastCareerButton?.isConnected)lastCareerButton.focus()};panel.querySelector('h2').focus({preventScroll:true});panel.scrollIntoView({behavior:fx.reducedMotion()?'auto':'smooth',block:'start'});
}
function catalog(){searchGrade=new URLSearchParams(location.search).get('grade');if(!banks[searchGrade])searchGrade='grades35';main.innerHTML=`<section class="page-intro"><a class="text-link" href="${banks[searchGrade].file}">Back to activity</a><h1>Explore jobs</h1></section><section class="catalog-tools card"><label>Find a job<input type="search" id="career-search" placeholder="Search jobs" autocomplete="off"></label></section><div class="category-filters" role="group" aria-label="Filter jobs by activity"><button type="button" data-category="all" aria-pressed="true">All jobs</button>${Object.entries(META).map(([code,m])=>`<button type="button" data-category="${code}" aria-pressed="false">${m.short}</button>`).join('')}</div><p id="search-count" role="status" aria-live="polite" class="muted"></p><section class="catalog-grid" id="catalog-grid" aria-label="Jobs"></section><section id="career-profile" class="card profile-panel" hidden></section>`;
 document.getElementById('career-search').addEventListener('input',renderCatalog);main.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{activeCategory=b.dataset.category;main.querySelectorAll('[data-category]').forEach(other=>other.setAttribute('aria-pressed',String(other===b)));renderCatalog();fx.tap()});renderCatalog();
}
function renderCatalog(){fx.stopReading();const query=document.getElementById('career-search').value.trim().toLocaleLowerCase(),b=banks[searchGrade],careers=CareerExplorerData.careers[searchGrade],ids=[...new Set((activeCategory==='all'?Object.values(b.jobs).flat():b.jobs[activeCategory]))];const visible=ids.filter(id=>(careers[id].label+' '+careers[id].does).toLocaleLowerCase().includes(query));document.getElementById('career-profile').hidden=true;document.getElementById('search-count').textContent=`${visible.length} ${visible.length===1?'job':'jobs'}`;document.getElementById('catalog-grid').innerHTML=visible.length?visible.map(id=>`<button type="button" class="card catalog-job" data-job="${id}" aria-expanded="false" aria-controls="career-profile"><strong>${esc(careers[id].label)}</strong><span>${esc(careers[id].does)}</span></button>`).join(''):'<p class="empty-search">No jobs match. Try another word or choose “All jobs.”</p>';bindJobs(searchGrade)}
try{Object.values(banks).forEach(b=>scoring.validateQuestions(b.questions));const mode=document.body.dataset.page;if(mode==='hub')hub();else if(mode==='catalog')catalog();else{bank=banks[document.body.dataset.grade];if(!bank)throw Error('Unknown grade');restore();quizIntro()}}catch(error){console.error('Career Explorer could not load:',error);main.innerHTML='<p class="error-box">This activity could not load. Please refresh and try again.</p>'}
})();
